<script setup lang="ts">import {ref,onMounted} from 'vue';import {reviews} from '../stores/reviews';import {reports} from '../stores/reports';import {isAdmin} from '../stores/auth';import {request,downloadCsv} from '../api/client';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import StatusPill from '../components/common/StatusPill.vue';import MatchLedger from '../components/MatchLedger.vue';const expanded=ref('');const {error,busy,act}=useTask();onMounted(()=>Promise.all([reviews.load(),reports.load()]));function approve(id:string){act(async()=>{await request('/reviews/'+id+'/approve','POST');await reviews.load()})}function publish(id:string){act(async()=>{await reports.create({review_id:id,title:'结算勾稽底稿 '+new Date().toLocaleDateString()})})}function download(id:string){act(()=>downloadCsv(id))}</script><template><PageHeading index="05 / 复核归档" title="让匹配结果，带着原始口径离开。" note="管理员批准后保存输入快照、两阶段候选和未配项。导出保持整数分与输入哈希，不向任何银行或真实账本写入。"/><Notice :message="error"/><div class="two-col"><section><h2>人工复核</h2><article v-for="r in reviews.items.value" :key="r.id" class="review-row"><StatusPill :status="r.state"/><p>{{r.action}}</p><small>{{r.reviewer||'等待管理员批准'}}</small><div v-if="isAdmin()" class="actions"><button v-if="r.state==='submitted'" @click="approve(r.id)" :disabled="busy">批准匹配复核</button><button v-if="r.state==='approved'" class="secondary" @click="publish(r.id)" :disabled="busy">生成勾稽快照</button></div></article></section><section><h2>批准底稿</h2><article v-for="r in reports.items.value" :key="r.id" class="report-row"><p class="eyebrow">APPROVED RECONCILIATION</p><h3>{{r.title}}</h3><p>一对一{{r.snapshot.result.counts.one_to_one}} / 合并{{r.snapshot.result.counts.merged}} · {{r.snapshot.reviewer}}</p><div class="actions"><button @click="download(r.id)">下载勾稽 CSV ↓</button><button class="secondary" @click="expanded=expanded===r.id?'':r.id">查看候选快照</button></div><MatchLedger v-if="expanded===r.id" :rows="r.snapshot.result.phase_one.matches.concat(r.snapshot.result.phase_two.groups)"/></article></section></div></template>
